"""
Independent, freshly-written (no shared code with the Executor's path1.py /
semaev_path2.py) re-verification of M1/M2 for m=4 and m=5 on two panel
curves: RO1 (p=103,A=1,B=71) and CM2 (p=103,A=23,B=27), N=115 and N=100
respectively. Own PRNG (Python's random module, MT19937), own seed, own
independent implementation of F_{p^2} arithmetic and the chord-tangent
addition law, and the A-3 predicted-permutation formula re-derived from
scratch (not copied).
"""
import random
import itertools

def legendre_symbol(a, p):
    a %= p
    if a == 0:
        return 0
    r = pow(a, (p - 1) // 2, p)
    return 1 if r == 1 else -1

def tonelli_shanks_sqrt(a, p):
    """Return smallest nonneg sqrt of QR a mod p (p odd prime). Simple search
    is fine for the toy p here; independent from the Executor's table method."""
    a %= p
    for x in range(p):
        if (x * x) % p == a:
            return x
    raise ValueError("no sqrt found")

class GF2:
    """F_{p^2} = F_p[u]/(u^2 - n), n a fixed nonresidue. Elements (a,b)=a+bu."""
    def __init__(self, p):
        self.p = p
        n = 2
        while legendre_symbol(n, p) != -1:
            n += 1
        self.n = n

    def add(self, x, y): return ((x[0]+y[0]) % self.p, (x[1]+y[1]) % self.p)
    def sub(self, x, y): return ((x[0]-y[0]) % self.p, (x[1]-y[1]) % self.p)
    def neg(self, x): return ((-x[0]) % self.p, (-x[1]) % self.p)
    def mul(self, x, y):
        a,b = x; c,d = y; p = self.p; n = self.n
        return ((a*c + b*d*n) % p, (a*d + b*c) % p)
    def sqr(self, x): return self.mul(x,x)
    def inv(self, x):
        a,b = x; p = self.p; n = self.n
        denom = (a*a - n*b*b) % p
        dinv = pow(denom, p-2, p)
        return ((a*dinv) % p, ((-b)*dinv) % p)
    def div(self, x, y): return self.mul(x, self.inv(y))
    def scal(self, k, x): return ((k*x[0]) % self.p, (k*x[1]) % self.p)
    def from_fp(self, a): return (a % self.p, 0)
    def eq(self, x, y): return x[0]%self.p==y[0]%self.p and x[1]%self.p==y[1]%self.p
    def frob(self, x): return (x[0] % self.p, (-x[1]) % self.p)  # p-th power map

def ec_add(F, P, Q, A):
    if P is None: return Q
    if Q is None: return P
    X1,Y1 = P; X2,Y2 = Q
    if F.eq(X1,X2):
        if F.eq(Y1, F.neg(Y2)):
            return None
        lam = F.div(F.add(F.scal(3, F.sqr(X1)), A), F.scal(2, Y1))
    else:
        lam = F.div(F.sub(Y2,Y1), F.sub(X2,X1))
    X3 = F.sub(F.sub(F.sqr(lam), X1), X2)
    Y3 = F.sub(F.mul(lam, F.sub(X1,X3)), Y1)
    return (X3,Y3)

def ec_neg(F, P):
    if P is None: return None
    X,Y = P
    return (X, F.neg(Y))

def sqrt_fp2(F, c):
    """Square root of c in F_p, in F_{p^2}. Returns (root, chi)."""
    p = F.p
    c %= p
    if c == 0:
        return (0,0), 0
    chi = legendre_symbol(c, p)
    if chi == 1:
        r = tonelli_shanks_sqrt(c, p)
        return (r, 0), 1
    else:
        # (c * n^{-1}) is a QR
        ninv = pow(F.n, p-2, p)
        s2 = (c * ninv) % p
        r = tonelli_shanks_sqrt(s2, p)
        return (0, r), -1

def run_cell(p, A, B, m, n_trials, rng):
    F = GF2(p)
    A_fp2 = F.from_fp(A)
    nviol = 0
    nmatch = 0
    nadmissible = 0
    excluded = 0
    n_signs = m - 2  # 2^(m-2) roots, eps_1 fixed +1, eps_2..eps_{m-1} free
    sign_keys = list(itertools.product((1,-1), repeat=n_signs))
    for _ in range(n_trials):
        xs = [rng.randrange(p) for _ in range(m-1)]
        if len(set(xs)) < len(xs):
            excluded += 1
            continue
        fvals = [(x**3 + A*x + B) % p for x in xs]
        if any(fv == 0 for fv in fvals):
            excluded += 1
            continue
        base = []
        chis = []
        for x, fv in zip(xs, fvals):
            y, chi = sqrt_fp2(F, fv)
            base.append(((F.from_fp(x), y)))
            chis.append(chi)
        # enumerate signed sums: P_1 + eps_2 P_2 + ... + eps_{m-1} P_{m-1}
        P1 = base[0]
        partial = {(): P1}
        for Pi in base[1:]:
            negPi = ec_neg(F, Pi)
            new_partial = {}
            for key, pt in partial.items():
                new_partial[key+(1,)] = ec_add(F, pt, Pi, A_fp2)
                new_partial[key+(-1,)] = ec_add(F, pt, negPi, A_fp2)
            partial = new_partial
        if any(pt is None for pt in partial.values()):
            excluded += 1
            continue
        xvals = {}
        dup = False
        for key, pt in partial.items():
            xv = (pt[0][0] % p, pt[0][1] % p)
            if xv in xvals:
                dup = True; break
            xvals[xv] = key
        if dup:
            excluded += 1
            continue
        # observed permutation via Frobenius conjugation matching
        perm = {}
        ok = True
        for key, pt in partial.items():
            fX = F.frob(pt[0])
            if fX not in xvals:
                ok = False; break
            perm[key] = xvals[fX]
        if not ok:
            excluded += 1
            continue
        nadmissible += 1
        # cycle type
        keys = list(partial.keys())
        seen = set(); lengths=[]
        for k in keys:
            if k in seen: continue
            length=0; cur=k
            while cur not in seen:
                seen.add(cur); cur=perm[cur]; length+=1
            lengths.append(length)
        ctype = tuple(sorted(lengths))
        n_roots = 2**(m-2)
        identity_type = tuple([1]*n_roots)
        pure2_type = tuple([2]*(n_roots//2))
        if ctype not in (identity_type, pure2_type):
            nviol += 1
        # predicted permutation from A-3: Frob(sum eps_i P_i) = sum eps_i*chi_i P_i
        chi1 = chis[0]
        g = [chii*chi1 for chii in chis[1:]]
        predicted_perm = {}
        for key in sign_keys:
            new_key = tuple(k*gi for k,gi in zip(key, g))
            predicted_perm[key] = new_key
        if predicted_perm == perm:
            nmatch += 1
    return {
        "n_trials": n_trials, "n_admissible": nadmissible, "n_excluded": excluded,
        "M1_violations": nviol, "M2_matches": nmatch,
        "M2_fraction": nmatch/nadmissible if nadmissible else float('nan'),
    }

if __name__ == "__main__":
    rng = random.Random(1234567890)  # own independent seed, not the SHA256 scheme
    panel = [
        ("RO1", 103, 1, 71),
        ("CM2", 103, 23, 27),
    ]
    for name, p, A, B in panel:
        for m in (4, 5):
            res = run_cell(p, A, B, m, 2500, rng)
            print(name, "m=",m, res)

