"""Independent recomputation of H-MONO-45183a step B-2's forced M4 values on
4 panel curve-m cells, from raw (tau, N) alone (own arithmetic)."""
from fractions import Fraction as F
cells = [
    ("RO2", 2, 212, "m4"), ("RO2", 2, 212, "m5"),
    ("RO3", 4, 456, "m4"), ("RO3", 4, 456, "m5"),
    ("CM2", 4, 100, "m4"), ("CM2", 4, 100, "m5"),
]
reported = {
    ("RO2","m4"): 0.02830, ("RO2","m5"): 0.26415,
    ("RO3","m4"): 0.03947, ("RO3","m5"): 0.29825,
    ("CM2","m4"): 0.18000, ("CM2","m5"): 1.36000,
}
for name, tau, N, m in cells:
    if m == "m4":
        forced = F(6*(tau-1), N)
    else:
        forced = F(16*tau, N) + F(24*(tau-1), N)
    rep = reported[(name,m)]
    print(f"{name} {m}: forced={float(forced):.5f} ({forced}) reported={rep:.5f} match={abs(float(forced)-rep)<1e-4}")
